Actionscript.script:
onClipEvent (load) {
	var skin:MovieClip = this._parent;
	var placement:Object = skin.__dressupPlacementIdentity;
	var 自机 = placement.actor;
	var 武器类型名 = "武器类型:dominator";
	var 动画帧名 = "dominator动画帧";
	var 击杀模式动画帧上限 = 50;
	var 分解模式动画帧上限 = 95;
	this.获得动画时长 = function()
	{
		return (自机[武器类型名] == "麻醉模式" ? 1 : (自机[武器类型名] == "分解模式" ? 分解模式动画帧上限 : 击杀模式动画帧上限));
	};
	var 改变武器类型许可 = true;
	this.判断是否展开 = function()
	{
		return 自机.攻击模式 == "手枪" and 自机[武器类型名] != "麻醉模式";
	};
	this.展开动画 = function()
	{
		//_root.发布调试消息(自机[武器类型名] + this.获得动画时长());
		if (自机[动画帧名] < this.获得动画时长())
		{
			if(自机[动画帧名] == 2){
				改变武器类型许可 = true;
			}
			自机[动画帧名] += 1;
		}else{
			改变武器类型许可 = true;
		}
	};
	this.折叠动画 = function()
	{
		if (自机[动画帧名] > 1)
		{
			自机[动画帧名] -= 1;
		}else{
			改变武器类型许可 = true;
		}
	};


	gotoAndStop(自机[动画帧名]);
	this.onEnterFrame = function()
	{
		if (placement == undefined || placement.actor == undefined || skin.__dressupPlacementIdentity !== placement
				|| 自机.__playerStatBody !== placement.body || 自机.手枪 !== placement.item) return;
		var 自机类型 = _root.获得父节点(this, 2)._name;
		if (Key.isDown(_root.武器变形键) and (自机[武器类型名] == "麻醉模式" or 自机[武器类型名] == "击杀模式" or 自机[武器类型名] == "分解模式") and 改变武器类型许可 and 自机.攻击模式 == "手枪" and 自机类型 == "枪")
		{
			if (自机[动画帧名] == 击杀模式动画帧上限 or 自机[动画帧名] == 分解模式动画帧上限 or 自机[动画帧名] <= 3)
			{
				if(自机[动画帧名]!=3){
					改变武器类型许可 = false;
				}
				if (自机[武器类型名] == "击杀模式")
				{
					自机[动画帧名] = 击杀模式动画帧上限;
				}
				else if (自机[武器类型名] == "分解模式")
				{
					自机[动画帧名] = 分解模式动画帧上限;
				}
				else if (自机[武器类型名] == "麻醉模式")
				{
					自机[动画帧名] = 1;
				}
				if (_root.玩家属性投影.变形手枪命令(skin,placement,自机[武器类型名],false)) {
					_root.发布消息("dominator切换为[" + 自机[武器类型名] + "]");
					if (_root.控制目标 == 自机._name) _root.玩家必要信息界面.子弹数 = 自机.手枪属性.capacity - 自机.手枪射击次数[自机.手枪.name];
				}
			}

		}
		this[this.判断是否展开() ? '展开动画' : '折叠动画']();
		gotoAndStop(自机[动画帧名]);
		if(自机[动画帧名]== 1 and 自机[武器类型名] != "麻醉模式"){
			_root.玩家属性投影.变形手枪命令(skin,placement,自机[武器类型名],true);
		}
	};
}
